builder.Services
    .AddGraphQLServer()
    .AddQueryType<Query>()
    .AddDefaultQueryStorage();

// In production, replace with a persistent store
builder.Services.AddSingleton<IQueryStorage, InMemoryQueryStorage>();

import { ApolloClient, InMemoryCache, HttpLink, ApolloLink } from '@apollo/client';

const apqLink = new ApolloLink((operation) => {
  const queryHash = createHash('sha256')
    .update(operation.query)
    .digest('hex');

  operation.setContext({
    headers: {
      'x-graphql-query-hash': queryHash
    }
  });

  return toPromise(httpLink.request(operation));
});

const client = new ApolloClient({
  link: apqLink,
  cache: new InMemoryCache()
});
